<?php
use App\Support\Auth;
$activeScanContext = scan_active_context();
$activeScan = $activeScanContext['run'];
$activeScanStale = (bool)($activeScanContext['stale'] ?? false);
$activeScanExists = (bool)($activeScanContext['exists'] ?? false);
$activeScanPercent = $activeScanContext['progress_percent'] ?? null;
$flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jura Server Guard</title><style>body{font-family:system-ui;margin:0;background:#0f172a;color:#e2e8f0}a{color:#93c5fd}.nav{background:#111827;padding:14px 24px;display:flex;gap:14px;align-items:center}.wrap{padding:24px}.card{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:18px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}table{width:100%;border-collapse:collapse;background:#1e293b}th,td{border-bottom:1px solid #334155;padding:9px;text-align:left;vertical-align:top}code,pre{background:#020617;color:#bae6fd;border-radius:6px;padding:3px 6px}pre{padding:12px;overflow:auto}.badge{border-radius:999px;padding:3px 8px;font-size:12px}.critical{background:#7f1d1d}.high{background:#b45309}.medium{background:#854d0e}.low{background:#166534}.btn{background:#2563eb;color:white;border:0;border-radius:6px;padding:7px 10px;cursor:pointer}.btn[disabled]{background:#475569;cursor:not-allowed}.danger{background:#dc2626}.warn{background:#ea580c}.muted{color:#94a3b8}.input{background:#020617;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:8px}.small{font-size:12px;padding:3px 7px}.nowrap{white-space:nowrap}.uri-cell{max-width:420px;overflow-wrap:anywhere}.details-row td{background:#0f172a}.details-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.details-grid .wide{grid-column:1/-1}.actions{display:flex;gap:8px;flex-wrap:wrap}.scan-form{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.flash{background:#064e3b;border:1px solid #10b981;border-radius:10px;padding:12px 16px;margin-bottom:16px}.scan-banner{border-radius:12px;padding:14px 16px;margin-bottom:16px;border:1px solid #334155;background:#1e3a8a}.scan-banner.stale{background:#7c2d12;border-color:#fb923c}.scan-banner h2{margin:0 0 6px}.scan-banner .meta{display:flex;gap:14px;flex-wrap:wrap}.scan-banner form{display:inline}</style></head><body><div class="nav"><b>Jura Server Guard</b><a href="/">Dashboard</a><a href="/users">Users</a><a href="/sites">Sites</a><a href="/findings">Findings</a><a href="/logs">Logs</a><a href="/file-changes">File changes</a><a href="/quarantine">Quarantine</a><a href="/backups">Backups</a><a href="/rules">Rules</a><a href="/settings">Settings</a><span style="margin-left:auto" class="muted"><?= e(Auth::user()['email'] ?? '') ?></span><a href="/logout">Logout</a></div><main class="wrap"><?php if($flash): ?><div class="flash"><?= e($flash) ?></div><?php endif ?><?php if($activeScanExists && $activeScan): ?><div id="active-scan-banner" class="scan-banner <?= $activeScanStale ? 'stale' : '' ?>"><h2><?= $activeScanStale ? 'Stale scan detected' : 'Active scan running' ?></h2><div class="meta"><span>Scan #<?= e($activeScan['id']) ?> <?= e($activeScan['scope_type'] ?? '') ?> <?= e($activeScan['scope_value'] ?? '') ?></span><span>Last heartbeat: <?= e($activeScan['last_heartbeat_at'] ?? 'n/a') ?></span><span>PID: <?= e($activeScan['pid'] ?? 'n/a') ?></span><span>Files scanned: <?= e($activeScan['files_scanned'] ?? 0) ?> / <?= e($activeScan['total_files_estimated'] ?? '?') ?></span><?php if($activeScanPercent !== null): ?><span><?= e($activeScanPercent) ?>%</span><?php endif ?></div><p class="muted"><?= e($activeScan['progress_message'] ?? $activeScan['current_path'] ?? '') ?></p><div class="actions"><form method="post" action="/scan/stop"><button class="btn danger small">Stop</button></form><?php if($activeScanStale): ?><form method="post" action="/scan/cleanup-stale"><button class="btn warn small">Cleanup stale scan</button></form><form method="post" action="/scan/unlock"><button class="btn warn small">Force unlock</button></form><?php endif ?></div></div><?php endif ?><?= $content ?? '' ?></main><?php if($activeScanExists): ?><script>setInterval(function(){fetch('/scan/active.json',{headers:{'Accept':'application/json'}}).then(r=>r.json()).then(d=>{if(!d.exists){location.reload();return;}var b=document.getElementById('active-scan-banner');if(!b){location.reload();return;}b.className='scan-banner '+(d.stale?'stale':'');b.querySelector('h2').textContent=d.stale?'Stale scan detected':'Active scan running';});},4000);</script><?php endif ?></body></html>
